<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityLoginProviderVO;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;

trait UserFederatedIdentityLoginProviderAccessor
{
    private UserFederatedIdentityLoginProviderVO $_loginProvider;
    public function getLoginProvider(): TenantLoginProviderRef
    {
        return $this->_loginProvider->value();
    }
    public function loginProvider(): UserFederatedIdentityLoginProviderVO
    {
        return $this->_loginProvider;
    }
    public function isLoginProviderChanged(?self $original = null): bool
    {
        return !$this->_loginProvider->equals($original?->_loginProvider);
    }
    public function withLoginProvider(UserFederatedIdentityLoginProviderVO|TenantLoginProviderRef $loginProvider): self
    {
        $copy = clone $this;
        $copy->_loginProvider = UserFederatedIdentityLoginProviderVO::from($loginProvider);
        return $copy;
    }
}
